/* One Wayfarer; shared equipment, sparse builds and protected possessions. */
'use strict';
const LOADOUT_NAMES=['One-handed melee','Two-handed melee','Ranged'];
const L6={itemRecord,playerCarry,makeSave,validSave,createUI,refreshInv,showDetail,configureItemActions,inventoryPriceBadge,showTitle,showControls,toggleInv,updateHUD};
let LOADOUTS={version:1,active:0,shared:{},builds:[{},{},{}]},loadoutEditing=0;
function weaponBuild(it){return !it||it.slot!=='weapon'?-1:it.def.ranged||it.def.magic?2:it.hands===2?1:0;}
function ownedEquipment(){return [...new Map([...Object.values(player?.gear||{}),...(player?.bag||[])].filter(Boolean).map(it=>[it.id,it])).values()];}
function loadoutRecord(){const ordered=b=>Object.fromEntries(SLOTS.filter(s=>b[s]).map(s=>[s,b[s]]));return{version:1,active:LOADOUTS.active,shared:ordered(LOADOUTS.shared),builds:LOADOUTS.builds.map(ordered)};}
function initializeLoadouts(carry,snapshot){RUN.class='wayfarer';const items=ownedEquipment(),byId=new Map(items.map(it=>[it.id,it])),saved=snapshot?.player?.loadouts||carry?.loadouts;const clean=map=>Object.fromEntries(SLOTS.filter(s=>byId.get(map?.[s])?.slot===s).map(s=>[s,map[s]]));
 if(saved&&saved.version===1&&saved.builds?.length===3){LOADOUTS={version:1,active:clamp(saved.active|0,0,2),shared:clean(saved.shared),builds:saved.builds.map(clean)};}
 else{const active=Math.max(0,weaponBuild(player.gear.weapon));LOADOUTS={version:1,active,shared:Object.fromEntries(SLOTS.filter(s=>player.gear[s]).map(s=>[s,player.gear[s].id])),builds:[{},{},{}]};for(let i=0;i<3;i++){const best=weaponBuild(player.gear.weapon)===i?player.gear.weapon:items.filter(it=>weaponBuild(it)===i).sort((a,b)=>b.score-a.score)[0];if(best)LOADOUTS.builds[i].weapon=best.id;}if(!LOADOUTS.shared.offhand){const shield=items.filter(it=>it.slot==='offhand').sort((a,b)=>b.score-a.score)[0];if(shield)LOADOUTS.shared.offhand=shield.id;}}
 loadoutEditing=LOADOUTS.active;
}
function gearForBuild(index=LOADOUTS.active){const byId=new Map(ownedEquipment().map(it=>[it.id,it])),gear={...player.gear};for(const s of SLOTS){const id=LOADOUTS.builds[index]?.[s]??(!gear[s]?LOADOUTS.shared[s]:null),it=byId.get(id);if(it&&it.slot===s)gear[s]=it;}if(gear.weapon?.hands===2)gear.offhand=null;return gear;}
function itemBuildNames(it){if(!it)return[];const names=[];if(Object.values(LOADOUTS.shared).includes(it.id))names.push('Shared gear');LOADOUTS.builds.forEach((b,i)=>{if(Object.values(b).includes(it.id))names.push(LOADOUT_NAMES[i]);});return names;}
function itemProtected(it){return!!it&&(!!it.locked||itemBuildNames(it).length>0||Object.values(player.gear).some(q=>q?.id===it.id));}
sellableItems=function(){return player.bag.filter(it=>!it.consumable&&!itemProtected(it));};
function sellCommonGear(){const sold=new Set(sellableItems().filter(it=>it.rarity<2).map(it=>it.id)),gold=player.bag.filter(it=>sold.has(it.id)).reduce((n,it)=>n+8+it.ilvl*3,0);player.bag=player.bag.filter(it=>!sold.has(it.id));player.gold+=gold;selected=null;saveGame(true);refreshInv();showDetail(null);toast('Sold spare gear · +'+gold+' gold','#dfc78f');return gold;}
itemRecord=function(it){const d=L6.itemRecord(it);if(d)d.locked=!!it.locked;return d;};
playerCarry=function(){return{...L6.playerCarry(),loadouts:loadoutRecord()};};
makeSave=function(){const d=L6.makeSave();d.build='6 · One Wayfarer, Three Builds';d.player.loadouts=loadoutRecord();d.run.class='wayfarer';return d;};
validSave=function(d){if(!L6.validSave(d))return false;const records=[...d.player.bag,...Object.values(d.player.gear),...(d.vendor?.stock||[]).map(q=>q.item),...(d.drops||[]).map(q=>q.item)].filter(Boolean);if(records.some(it=>it.locked!==undefined&&typeof it.locked!=='boolean'))return false;const b=d.player.loadouts;if(!b)return true;const byId=new Map(records.map(it=>[it.id,it])),map=m=>m&&typeof m==='object'&&!Array.isArray(m)&&Object.entries(m).every(([s,id])=>SLOTS.includes(s)&&Number.isSafeInteger(id)&&id>0&&(!byId.has(id)||byId.get(id).slot===s));return b.version===1&&Number.isInteger(b.active)&&b.active>=0&&b.active<3&&map(b.shared)&&Array.isArray(b.builds)&&b.builds.length===3&&b.builds.every(map);};
function cancelEquipmentAttack(){const a=player.rig.anim;player.atkCd=Math.max(player.atkCd||0,a.atkT>=0?Math.max(.22,Math.min(1,a.atkDur-a.atkT)):.18);a.atkT=-1;a.phase=3;a.phaseT=0;a.prevPts=null;a.propPrev=null;a.startPose=null;a.didShot=false;a.hitSet=new Set();a.propHitSet=new Set();player.blocking=false;player.comboT=0;mouse.right=0;}
function commitEquipment(gear){const owned=ownedEquipment(),byId=new Map(owned.map(it=>[it.id,it])),next={};for(const s of SLOTS){const it=gear[s];next[s]=it&&byId.get(it.id)?.slot===s?byId.get(it.id):null;}if(next.weapon?.hands===2)next.offhand=null;const changed=SLOTS.some(s=>player.gear[s]?.id!==next[s]?.id);if(!changed)return false;cancelEquipmentAttack();const used=new Set(Object.values(next).filter(Boolean).map(it=>it.id));player.gear=next;player.bag=owned.filter(it=>!used.has(it.id));for(const s of SLOTS)if(next[s]&&!LOADOUTS.builds[LOADOUTS.active][s])LOADOUTS.shared[s]=next[s].id;const hp=player.hp,stam=player.stam;renderEquip(player);player.hp=Math.min(hp,player.maxhp);player.stam=Math.min(stam,player.maxstam);updateRig(player,0);return true;}
function loadoutReady(index){return weaponBuild(gearForBuild(index).weapon)===index;}
function activateLoadout(index,fromInventory=false){if(!Number.isInteger(index)||index<0||index>2||!player||player.dead||loadingLevel||!G.running||G.paused||(!fromInventory&&G.invOpen))return false;if(!loadoutReady(index)){toast('Assign a '+LOADOUT_NAMES[index].toLowerCase()+' weapon in Equipment first.','#ddbd91');return false;}const gear=gearForBuild(index);LOADOUTS.active=index;const changed=commitEquipment(gear);if(!G.invOpen)loadoutEditing=index;saveGame(true);updateHUD();if(G.invOpen)refreshInv();if(changed)toast(LOADOUT_NAMES[index]+' · ready','#b7d6cc');return true;}
function cycleLoadout(){for(let n=1;n<=3;n++){const i=(LOADOUTS.active+n)%3;if(loadoutReady(i))return activateLoadout(i);}return false;}
function selectLoadoutTab(index){loadoutEditing=index;selected=null;bagPage=0;refreshInv();showDetail(null);}
function assignLoadoutItem(it,index=loadoutEditing){if(!it||it.consumable||!ownedEquipment().some(q=>q.id===it.id)||!SLOTS.includes(it.slot))return false;if(index>=0&&it.slot==='weapon'&&weaponBuild(it)!==index){toast('This tab uses '+LOADOUT_NAMES[index].toLowerCase()+' weapons.','#d9bb92');return false;}const target=index<0?LOADOUTS.shared:LOADOUTS.builds[index];target[it.slot]=it.id;if(index<0){if(it.slot==='weapon')LOADOUTS.active=weaponBuild(it);delete LOADOUTS.builds[LOADOUTS.active][it.slot];const gear=gearForBuild();gear[it.slot]=it;commitEquipment(gear);}else if(index===LOADOUTS.active)commitEquipment(gearForBuild());selected=it;saveGame(true);refreshInv();showDetail(it);return true;}
function clearLoadoutSlot(slot,index=loadoutEditing){const target=index<0?LOADOUTS.shared:LOADOUTS.builds[index];if(!target||!target[slot])return;delete target[slot];if(index===LOADOUTS.active&&player.gear[slot])LOADOUTS.shared[slot]=player.gear[slot].id;if(index<0||index===LOADOUTS.active)commitEquipment(gearForBuild());saveGame(true);refreshInv();if(selected)showDetail(selected);}
equipItem=function(it){if(G.invOpen&&!TRADE.active)return assignLoadoutItem(it,loadoutEditing);if(!it||it.consumable||!ownedEquipment().some(q=>q.id===it.id))return false;if(it.slot==='weapon'){LOADOUTS.active=weaponBuild(it);LOADOUTS.builds[LOADOUTS.active].weapon=it.id;}else{if(it.slot==='offhand'&&player.gear.weapon?.hands===2){if(!loadoutReady(0)){toast('Choose a one-handed weapon before equipping a shield.','#ddbd91');return false;}LOADOUTS.active=0;}LOADOUTS.shared[it.slot]=it.id;delete LOADOUTS.builds[LOADOUTS.active][it.slot];}const gear=gearForBuild();gear[it.slot]=it;commitEquipment(gear);selected=it;saveGame(true);refreshInv();showDetail(it);return true;};
function toggleItemLock(it){if(!it||it.consumable||!ownedEquipment().some(q=>q.id===it.id))return false;it.locked=!it.locked;saveGame(true);refreshInv();showDetail(it);return true;}
// Preserve armor-set optimization while restricting the weapon to the active build.
autoEquip=function(){if(!player||player.dead)return;const owned=ownedEquipment(),slots=SLOTS.filter(s=>s!=='weapon');let best={...player.gear},score=loadoutScore(best);const top=(slot,set)=>owned.filter(it=>it.slot===slot&&(!set||it.armorSet===set)&&(slot!=='weapon'||weaponBuild(it)===LOADOUTS.active)).sort((a,b)=>b.score-a.score)[0]||null;const evaluate=gear=>{if(gear.weapon?.hands===2)gear.offhand=null;const value=loadoutScore(gear);if(value>score+.001){score=value;best={...gear};}};const weapon=top('weapon');if(weapon){const raw={weapon};for(const s of slots)raw[s]=s==='offhand'&&weapon.hands===2?null:top(s)||player.gear[s];evaluate({...raw});for(const key of Object.keys(ARMOR_SETS)){const choices=slots.filter(s=>!(s==='offhand'&&weapon.hands===2)&&top(s,key));for(const count of[3,5]){if(choices.length<count)continue;const visit=(i,taken,gear)=>{if(taken===count){evaluate(gear);return;}for(let j=i;j<=choices.length-(count-taken);j++){const slot=choices[j];visit(j+1,taken+1,{...gear,[slot]:top(slot,key)});}};visit(0,0,{...raw});}}}const changed=SLOTS.filter(s=>best[s]&&player.gear[s]?.id!==best[s].id);for(const s of changed)LOADOUTS.builds[LOADOUTS.active][s]=best[s].id;commitEquipment(best);saveGame(true);selected=null;refreshInv();showDetail(null);toast(changed.length?'Optimized '+LOADOUT_NAMES[LOADOUTS.active].toLowerCase()+' · '+changed.length+' upgrades':'Already wearing your best gear for this build','#bdd6b1');};
inventoryPriceBadge=function(it){return L6.inventoryPriceBadge(it)+(it.locked?'<span class="itemProtectionBadge" title="Locked">🔒</span>':itemBuildNames(it).length?'<span class="itemProtectionBadge" title="Saved in a build">◆</span>':'');};
function drawLoadoutPanel(){if(!player)return;const stock=TRADE.active&&TRADE.side==='vendor';$('loadoutBar').hidden=TRADE.active;$('loadoutGearTitle').textContent=TRADE.active?'Currently equipped':loadoutEditing<0?'Shared equipment':LOADOUT_NAMES[loadoutEditing];$('loadoutStatus').textContent='Active: '+LOADOUT_NAMES[LOADOUTS.active]+' · Only saved slots switch. Blank slots keep the gear you are wearing.';for(let i=-1;i<3;i++){const b=$(i<0?'loadoutShared':'loadoutTab'+i);b.classList.toggle('on',loadoutEditing===i);b.setAttribute('aria-selected',String(loadoutEditing===i));if(i>=0)b.textContent=(i+1)+' · '+LOADOUT_NAMES[i]+(LOADOUTS.active===i?' · Active':'');}$('activateBuild').hidden=loadoutEditing<0||TRADE.active;$('activateBuild').disabled=loadoutEditing<0||!loadoutReady(loadoutEditing);$('activateBuild').textContent=loadoutEditing===LOADOUTS.active?'Build active':'Use this build';$('activateBuild').onclick=()=>activateLoadout(loadoutEditing,true);$('btnAuto').textContent='Optimize active build';$('sellAllBag').textContent='Sell spare gear · keep locked & saved items';
 if(TRADE.active)return;const gear=loadoutEditing<0?Object.fromEntries(SLOTS.map(s=>[s,ownedEquipment().find(it=>it.id===LOADOUTS.shared[s])||null])):gearForBuild(loadoutEditing),map=loadoutEditing<0?LOADOUTS.shared:LOADOUTS.builds[loadoutEditing],list=$('gearList');$('gearScore').textContent=loadoutEditing<0?'':gearScore({gear});list.innerHTML='';for(const s of SLOTS){const pinned=ownedEquipment().find(it=>it.id===map[s]),it=pinned||gear[s],wrap=document.createElement('div');wrap.className='loadoutSlot';const btn=document.createElement('button');btn.type='button';btn.className='gear';inventoryFocus(btn,'loadout:'+loadoutEditing+':'+s);const stowed=s==='offhand'&&loadoutEditing>=0&&gear.weapon?.hands===2;btn.innerHTML='<div class="ic" style="color:'+(it?RARITY[it.rarity].c:'#587078')+'">'+SLOT_ICON[s]+'</div><div><div class="nm">'+(it?escaped(it.name):'Keep current gear')+'</div><div class="sl">'+(s==='weapon'?'Weapon':s==='offhand'?'Shield':ARMORS[s].n)+' · '+(stowed?'Stowed for two hands':pinned?(loadoutEditing<0?'Shared by builds':'This build only'):'Shared / current')+(it?.locked?' · Locked':'')+'</div></div>';btn.onclick=()=>{if(it){selected=it;showDetail(it);}else{bagFilter=s==='weapon'?'weapon':s==='offhand'?'offhand':'armor';bagPage=0;selected=null;refreshInv();showDetail(null);}};wrap.appendChild(btn);if(pinned){const clear=document.createElement('button');clear.type='button';clear.className='clearBuildSlot';inventoryFocus(clear,'clear:'+loadoutEditing+':'+s);clear.textContent='×';clear.title=loadoutEditing<0?'Clear shared assignment; keep currently worn gear':'Use shared gear for this slot';clear.setAttribute('aria-label',clear.title+' · '+s);clear.onclick=()=>clearLoadoutSlot(s);wrap.appendChild(clear);}list.appendChild(wrap);}}
configureItemActions=function(it){L6.configureItemActions(it);const owned=!!it&&!it.consumable&&ownedEquipment().some(q=>q.id===it.id),stock=TRADE.active&&TRADE.side==='vendor'&&!!vendorRow(it);$('btnLock').hidden=!owned||stock;$('btnLock').disabled=!owned;$('btnLock').textContent=it?.locked?'Unlock item':'Lock item';$('btnLock').setAttribute('aria-pressed',String(!!it?.locked));$('btnLock').onclick=()=>toggleItemLock(it);if(owned&&itemProtected(it)){$('btnDrop').disabled=true;$('btnDrop').onclick=()=>{};}
 if(owned&&!TRADE.active){const map=loadoutEditing<0?LOADOUTS.shared:LOADOUTS.builds[loadoutEditing],compatible=it.slot!=='weapon'||loadoutEditing<0||weaponBuild(it)===loadoutEditing,assigned=map[it.slot]===it.id;$('btnEquip').textContent=assigned?'Saved here':!compatible?'Choose matching weapon':loadoutEditing<0?'Equip shared':'Assign to this build';$('btnEquip').disabled=!compatible||assigned;$('btnEquip').onclick=()=>assignLoadoutItem(it);}
};
showDetail=function(it){L6.showDetail(it);if(!it){$('btnLock').hidden=true;return;}if(!it.consumable&&ownedEquipment().some(q=>q.id===it.id)){const names=itemBuildNames(it);$('dInfo').insertAdjacentHTML('beforeend','<p class="protectionNote">'+(it.locked?'🔒 Locked. Unlock to allow selling or dropping. ':'')+(names.length?'Saved in '+names.map(escaped).join(', ')+'. Clear its saved slots before selling.':'')+'</p>');}configureItemActions(it);};
refreshInv=function(){const focusKey=document.activeElement?.getAttribute?.('data-focus-key');L6.refreshInv();if(!player||!G.invOpen)return;drawLoadoutPanel();if(selected)configureItemActions(selected);if(focusKey)inventoryFocusNodes.get(focusKey)?.focus();};
createUI=function(){L6.createUI();$('inv').classList.add('loadoutInventory');$('invGrid').insertAdjacentHTML('beforebegin','<div id="loadoutBar"><div class="buildTabs" role="tablist" aria-label="Equipment builds"><button id="loadoutShared" role="tab">Shared gear</button><button id="loadoutTab0" role="tab"></button><button id="loadoutTab1" role="tab"></button><button id="loadoutTab2" role="tab"></button><button id="activateBuild" class="prim">Use this build</button></div><p id="loadoutStatus"></p></div>');$('loadoutShared').onclick=()=>selectLoadoutTab(-1);for(let i=0;i<3;i++)$('loadoutTab'+i).onclick=()=>selectLoadoutTab(i);for(let i=-1;i<3;i++){const b=$(i<0?'loadoutShared':'loadoutTab'+i);b.onkeydown=e=>{if(e.key!=='ArrowLeft'&&e.key!=='ArrowRight')return;e.preventDefault();const next=(i+1+(e.key==='ArrowRight'?1:3))%4-1;selectLoadoutTab(next);$(next<0?'loadoutShared':'loadoutTab'+next).focus();};}$('dBtns').insertAdjacentHTML('beforeend','<button id="btnLock" hidden>Lock item</button>');$('hotbar').insertAdjacentHTML('beforeend','<button id="loadoutCycle" class="slot pane" title="Cycle ready builds · V">1H<span class="key">V · BUILD</span></button>');$('loadoutCycle').onclick=()=>cycleLoadout();};
toggleInv=function(force){const opening=force??!G.invOpen;if(opening)loadoutEditing=LOADOUTS.active;L6.toggleInv(force);};
updateHUD=function(){L6.updateHUD();const b=$('loadoutCycle');if(b){b.innerHTML=['1H','2H','RNG'][LOADOUTS.active]+'<span class="key">V · BUILD</span>';b.title='Current: '+LOADOUT_NAMES[LOADOUTS.active]+' · 1 / 2 / 3 or V to switch';}};
showTitle=function(){L6.showTitle();const badge=$('buildMarker');if(badge)badge.textContent='ONE WAYFARER · THREE BUILDS';};
showControls=function(){L6.showControls();$('modalBody').insertAdjacentHTML('beforeend','<p><b>One Wayfarer, every weapon and armor type.</b> Press <b>1 / 2 / 3</b> for one-handed melee, two-handed melee, or ranged. Press <b>V</b> or tap the build button to cycle ready builds.</p><p>In Equipment, edit Shared gear for your defaults or select a build tab and assign specific items. Only populated build slots replace equipment. Blank slots keep whatever you are currently wearing, including armor from another build. Two-handed weapons temporarily stow your shield. Locked items and gear saved in any build are protected from every sell action.</p>');};
/* Shoulder boom: sweep its full offset, and sweep again after smoothing/shake. */
function cameraPointClear(p,r=.2){for(const x of[-r,0,r])for(const y of[-r,0,r])for(const z of[-r,0,r])if(solidWorld(p.x+x,p.y+y,p.z+z))return false;for(const b of nearby(blockBuckets,p.x,p.z)){if(b.crate?.open)continue;if(p.y+r>groundAt(b.x,b.z)-.25&&p.y-r<groundAt(b.x,b.z)+(b.height||2.6)&&Math.hypot(p.x-b.x,p.z-b.z)<b.r+r)return false;}return true;}
function cameraSweep(from,to){const delta=to.subtract(from),distance=delta.length(),steps=Math.max(1,Math.ceil(distance/.12));let last=from.clone();for(let n=1;n<=steps;n++){const p=from.add(delta.scale(n/steps));if(!cameraPointClear(p))break;last=p;}return last;}
updateCamera=function(dt){const focus=player.pos.add(V3(0,1.48,0)),cp=Math.cos(mouse.pitch),dir=V3(Math.sin(mouse.yaw)*cp,-Math.sin(mouse.pitch),Math.cos(mouse.yaw)*cp),right=V3(Math.cos(mouse.yaw),0,-Math.sin(mouse.yaw));const wanted=cameraSweep(focus,focus.subtract(dir.scale(4.8)).add(right.scale(1.05))),smooth=BABYLON.Vector3.Lerp(cam.position,wanted,1-Math.exp(-dt*15)),kick=SETTINGS.shake?(G.cameraKick||0):0;smooth.x+=Math.sin(G.time*103)*kick;smooth.y+=Math.cos(G.time*83)*kick;cam.position.copyFrom(cameraSweep(focus,smooth));G.cameraKick=(G.cameraKick||0)*Math.exp(-dt*18);cam.setTarget(focus.add(dir.scale(16)));};

function comparisonEquipment(){return G.invOpen&&!TRADE.active&&loadoutEditing>=0?gearForBuild(loadoutEditing):player.gear;}
function comparisonContext(){return G.invOpen&&!TRADE.active&&loadoutEditing>=0?'If assigned · '+LOADOUT_NAMES[loadoutEditing]:'If equipped';}
